class EditDateDialogController{constructor($mdDialog,toastrService,DispatchData,moment,job,title,fieldName,date,id){this._$mdDialog=$mdDialog;this._toastrService=toastrService;this._dispatchData=DispatchData;this._moment=moment;this._job=job;this.title=title;this.fieldName=fieldName;this.date=moment(date,"DD/MM/YYYY").toDate();this.id=id;this.isLoading=false}async submit(newDate){try{this.isLoading=true;await this._updateJobDetail(newDate)}catch(error){this._toastrService.showErrorToast(error.message)}finally{this.isLoading=false}let fieldName=this.fieldName.toLowerCase();let matchingField=Object.keys(this._job).find(key=>key.toLowerCase()===fieldName);if(matchingField){this._job[matchingField]=newDate}else{console.warn(`Field ${this.fieldName} not found in job object.`)}this._showMessageAndCloseDialog()}async _updateJobDetail(newDate){const formattedDate=this._formatDate(newDate);const callData={call:"updateDetailField",field:this.fieldName,value:formattedDate,jobID:this._job.id};if(this._job.bulkJob){await this._dispatchData.updateBulkJobDetail(this._job.id,callData.field,callData.value,this._job.charge,FirstName,ContactID)}else{await this._dispatchData.updateJobDetail(this._job.id,callData.field,callData.value,this._job.charge,FirstName,ContactID,this._job.preBook)}}_showMessageAndCloseDialog(){this._toastrService.showSuccessToast("Updated "+this.title);this._$mdDialog.hide(this._job)}_formatDate(date){return new Date(this._moment(date).format("YYYY-MM-DDTHH:mm"))}cancel(){this._$mdDialog.cancel()}}